-- Prevent unsafe unit deletion.\n-- Members and dependent pertinences must be detached first;\n-- accounting allocations/installments always block deletion.\nCREATE OR REPLACE FUNCTION public.prevent_unsafe_condominium_unit_delete()\nRETURNS trigger\nLANGUAGE plpgsql\nSET search_path = public\nAS $$\nDECLARE\n  v_members integer;\n  v_children integer;\n  v_alloc integer;\n  v_inst integer;\nBEGIN\n  SELECT count(*) INTO v_members\n  FROM public.condominium_members\n  WHERE condominium_id = old.condominium_id AND unit_id = old.id;\n\n  IF v_members > 0 THEN\n    RAISE EXCEPTION 'L''unità è associata a uno o più condòmini e non può essere eliminata. Rimuovi prima le associazioni.';\n  END IF;\n\n  SELECT count(*) INTO v_children\n  FROM public.condominium_units\n  WHERE condominium_id = old.condominium_id\n    AND id <> old.id\n    AND nullif(trim(coalesce(data->>'incorporatedInUnitId','')), '') = old.id::text;\n\n  IF v_children > 0 THEN\n    RAISE EXCEPTION 'L''unità è collegata come unità principale di una o più pertinenze e non può essere eliminata. Rimuovi prima i collegamenti.';\n  END IF;\n\n  SELECT count(*) INTO v_alloc\n  FROM public.condominium_expense_allocations\n  WHERE workspace_id = old.workspace_id AND condominium_id = old.condominium_id AND unit_id = old.id;\n\n  SELECT count(*) INTO v_inst\n  FROM public.condominium_installments\n  WHERE workspace_id = old.workspace_id AND condominium_id = old.condominium_id AND unit_id = old.id;\n\n  IF v_alloc > 0 OR v_inst > 0 THEN\n    RAISE EXCEPTION 'L''unità ha movimenti contabili o rate collegate e non può essere eliminata.';\n  END IF;\n\n  RETURN old;\nEND;\n$$;\n\nDROP TRIGGER IF EXISTS trg_prevent_unsafe_condominium_unit_delete ON public.condominium_units;\nCREATE TRIGGER trg_prevent_unsafe_condominium_unit_delete\nBEFORE DELETE ON public.condominium_units\nFOR EACH ROW EXECUTE FUNCTION public.prevent_unsafe_condominium_unit_delete();\n\nREVOKE EXECUTE ON FUNCTION public.prevent_unsafe_condominium_unit_delete() FROM public, anon, authenticated;\n